/* Trilheiros Gestão Premium V7 — operação, financeiro, relatórios, quartos, ônibus, checklist, histórico, lixeira e acessos */
(function(){
  if(typeof state==='undefined')return;
  const OWNER_EMAIL='trilheiros.roomt@gmail.com';
  const LS_FAV='trilheiros_v7_favorites';
  const LS_THEME='trilheiros_v7_theme';
  const LS_SESSION='trilheiros_v7_session_minutes';
  const DEFAULT_CHECKLIST=[
    ['transport','Transporte confirmado'],['guide','Guia/condutor confirmado'],['insurance','Seguro/lista enviada'],
    ['food','Alimentação confirmada'],['lodging','Hospedagem confirmada'],['equipment','Equipamentos separados'],
    ['participant_list','Lista de participantes revisada'],['whatsapp','Grupo/avisos enviados'],['payments','Pagamentos conferidos']
  ];
  const EMAIL_DEFAULTS={
    enabled:true,
    reminder_3d_subject:'🌿 {{passeio}} é esta semana! Tudo certo por aí?',
    reminder_3d_body:'Oi, {{nome}}! 😄\n\nOs Trilheiros passando para dar aquele toque: faltam só 3 dias para {{passeio}}! 🥾🌿\n\nJá está entrando no clima? Dá uma conferida rapidinha:\n✅ Data: {{data}}\n✅ Destino: {{destino}}\n✅ Horário de saída: {{saida}}\n✅ Participantes: {{participantes}}\n🎒 O que levar: {{levar}}\n📝 Recado do passeio: {{lembrete_extra}}\n\nSe estiver tudo certo, agora é só começar a contagem regressiva. 😄\n\nAqui ninguém vai só. 💚\nTrilheiros de Rondonópolis',
    reminder_1d_subject:'⛰️ É AMANHÃ! {{passeio}} te espera 🥾',
    reminder_1d_body:'Oi, {{nome}}! 😄\n\nÉ AMANHÃ! 🥾⛰️\nChegou a hora de separar a roupa, carregar o celular e preparar a animação porque {{passeio}} está logo ali!\n\n📅 Data: {{data}}\n📍 Destino: {{destino}}\n🕒 Saída: {{saida}}\n👥 Participantes: {{participantes}}\n🎒 O que levar: {{levar}}\n📝 Último recado: {{lembrete_extra}}\n🔖 Protocolo: {{protocolo}}\n\nConfira tudo hoje para amanhã ser só colocar o tênis e ir. 😄\n\nDinheiro volta, tempo não. Viva essa experiência! 💚\nTrilheiros de Rondonópolis',
    post_trip_enabled:false,
    post_trip_subject:'💚 E aí, como foi {{passeio}}?',
    post_trip_body:'Oi, {{nome}}! 😄\n\nEsperamos que {{passeio}} tenha rendido boas histórias e fotos incríveis.\n\nConta pra gente como foi sua experiência. Sua opinião ajuda muito a melhorar os próximos passeios:\n{{avaliacao_link}}\n\nObrigado por caminhar com a gente! 🌿\nTrilheiros de Rondonópolis'
  };

  state.role=state.role||'owner';
  state.dayTrip=state.dayTrip||'';
  state.dayOps=state.dayOps||{};
  state.generalSettings=state.generalSettings||{};
  state.feedback=state.feedback||[];

  const q=s=>document.querySelector(s), qa=s=>[...document.querySelectorAll(s)];
  const digits=v=>String(v||'').replace(/\D/g,'');
  const maskCpf=v=>{const n=digits(v);return n.length===11?`${n.slice(0,3)}.***.***-${n.slice(-2)}`:cpf(v)};
  const slug=v=>String(v||'arquivo').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const todayISO=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Cuiaba'});
  const dayDiff=iso=>{if(!iso)return 999;const [y,m,d]=String(iso).slice(0,10).split('-').map(Number),target=new Date(y,m-1,d),now=new Date();now.setHours(0,0,0,0);return Math.round((target-now)/86400000)};
  const roleCanFinance=()=>['owner','admin','finance'].includes(state.role);
  const roleCanManage=()=>['owner','admin'].includes(state.role);
  const roleCanOperate=()=>['owner','admin','support'].includes(state.role);

  function favs(){try{return new Set(JSON.parse(localStorage.getItem(LS_FAV)||'[]'))}catch{return new Set()}}
  function saveFavs(set){localStorage.setItem(LS_FAV,JSON.stringify([...set]))}
  window.toggleFavorite=function(id){const s=favs();s.has(id)?s.delete(id):s.add(id);saveFavs(s);renderAdmin()};

  function download(name,content,type='application/json'){const b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
  function csvEscape(v){const s=String(v??'');return /[;"\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s}
  function friendly(e){const s=String(e?.message||e||'Erro inesperado.');if(/permission/i.test(s))return'Você não tem permissão para esta ação.';if(/network|unavailable|offline/i.test(s))return'Esta ação precisa de internet. Conecte-se e tente novamente.';return s}
  function requireOnline(){if(!navigator.onLine){toast('Esta operação precisa de internet para ser concluída com segurança.','error');return false}return true}
  function closeModalV7(){document.getElementById('modal')?.remove()}
  window.closeModalV7=closeModalV7;
  try{modal.remove=closeModalV7}catch(_){ }

  async function audit(action,entity,entityId,summary,extra={}){
    try{if(!auth.currentUser)return;await db.collection('audit_logs').add({action,entity,entity_id:entityId||'',summary,extra,user_uid:auth.currentUser.uid,user_email:auth.currentUser.email||'',created_at:firebase.firestore.FieldValue.serverTimestamp()})}catch(_){ }
  }
  window.auditV7=audit;

  async function resolveRole(user){
    if(!user)return null;
    if((user.email||'').toLowerCase()===OWNER_EMAIL)return'owner';
    try{const s=await db.collection('admin_users').doc(user.uid).get();if(s.exists&&s.data().active!==false)return s.data().role||'support'}catch(_){ }
    return null;
  }

  window.adminRoute=async function(){
    app.innerHTML='<div class="empty" style="padding:100px">Carregando painel...</div>';
    await new Promise(r=>{const off=auth.onAuthStateChanged(()=>{off();r()})});
    const role=await resolveRole(auth.currentUser);
    if(role){state.role=role;adminApp()}else loginLayout();
  };
  try{adminRoute=window.adminRoute}catch(_){ }

  window.loginLayout=function(message=''){
    app.innerHTML=`<main class="loginPage"><section class="loginBrand">${brand()}<h1>Trilheiros Gestão Premium</h1><p>Operação, participantes, financeiro, relatórios e comunicação em um só lugar.</p></section><section class="loginCardWrap"><div class="loginCard"><span class="eyebrow">ACESSO ADMINISTRATIVO</span><h2>Entrar no painel</h2><p>Use seu e-mail e senha autorizados.</p><form id="login"><label><span>E-mail</span><input name="email" type="email" value="${OWNER_EMAIL}" required></label><label><span>Senha</span><input name="password" type="password" required></label><div id="m">${message?`<div class="msg error">${esc(message)}</div>`:''}</div><button class="btn primary wide" style="margin-top:16px">Entrar</button></form></div></section></main>`;
    q('#login').onsubmit=async e=>{e.preventDefault();const f=e.target;try{const c=await auth.signInWithEmailAndPassword(f.email.value.trim(),f.password.value);const role=await resolveRole(c.user);if(!role){await auth.signOut();throw Error('Este usuário não possui acesso ao painel.')}state.role=role;adminApp()}catch(x){q('#m').innerHTML=`<div class="msg error">${esc(friendly(x))}</div>`}}
  };
  try{loginLayout=window.loginLayout}catch(_){ }

  let idleTimer;
  function resetIdle(){clearTimeout(idleTimer);const mins=Math.max(5,Number(localStorage.getItem(LS_SESSION)||30));idleTimer=setTimeout(async()=>{if(location.pathname.startsWith('/admin')&&auth.currentUser){await auth.signOut();loginLayout('Sessão bloqueada por inatividade. Entre novamente.')}},mins*60000)}
  ['click','keydown','touchstart','mousemove'].forEach(ev=>document.addEventListener(ev,resetIdle,{passive:true}));

  window.adminApp=function(){state.tab='dashboard';app.innerHTML=adminShell();resetIdle();startSync()};
  try{adminApp=window.adminApp}catch(_){ }

  function navButton(tab,icon,label,allowed=true){return allowed?`<button data-tab="${tab}">${icon} ${label}</button>`:''}
  window.adminShell=function(){
    return `<main class="admin v7"><aside class="side" id="side">${brand()}<button class="mobileClose iconClose" onclick="toggleAdminSide(false)">✕</button><div class="roleBadge">${state.role==='owner'?'Proprietário':state.role==='admin'?'Administrador':state.role==='finance'?'Financeiro':'Apoio'}</div><nav class="nav"><div class="navGroup">GESTÃO</div>${navButton('dashboard','▦','Visão geral')}${navButton('trips','◫','Passeios')}${navButton('people','♟','Participantes')}${navButton('finance','R$','Financeiro',roleCanFinance())}<div class="navGroup">OPERAÇÃO</div>${navButton('day','☀','Dia do passeio',roleCanOperate())}${navButton('reports','▤','Relatórios')}${navButton('pending','!','Pendências')}<div class="navGroup">RELACIONAMENTO</div>${navButton('communications','✉','Comunicações',roleCanManage())}${navButton('feedback','★','Avaliações')}${navButton('notifications','🔔','Notificações')}<div class="navGroup">SISTEMA</div>${navButton('settings','⚙','Configurações',roleCanManage())}${navButton('audit','↺','Histórico',roleCanManage())}${navButton('trash','⌫','Lixeira',roleCanManage())}</nav><div class="sideBottom"><div class="sync online" id="sync">☁ Sincronizando...</div><button class="btn ghost wide" onclick="openInstallGuide()">⬇ Instalar aplicativo</button><button class="btn ghost wide" id="logout">Sair</button></div></aside><section class="adminMain"><header class="adminHead"><div class="adminTitleWrap"><button class="btn ghost mobileMenu" onclick="toggleAdminSide(true)">☰</button><div><span class="eyebrow">TRILHEIROS • PREMIUM V7</span><h1 id="pageTitle">Visão geral</h1></div></div><div class="adminV7Tools"><div class="globalSearchWrap"><span>⌕</span><input id="globalSearch" placeholder="Buscar nome, CPF, protocolo ou passeio"><div id="globalSearchResults" class="globalSearchResults"></div></div><span class="networkBadge online" id="networkBadge">● Online</span><button class="iconAction" id="themeToggle" title="Modo escuro">◐</button><button class="notifyBell" onclick="openNotifications()">🔔<span class="notifyCount" id="notifyCount"></span></button><button class="btn primary" id="newTrip" ${roleCanManage()?'':'disabled'}>+ Novo passeio</button></div></header><div class="adminContent" id="content"><div class="empty">Sincronizando dados...</div></div></section></main>`
  };
  try{adminShell=window.adminShell}catch(_){ }

  function applyTheme(){const dark=localStorage.getItem(LS_THEME)==='dark';document.documentElement.classList.toggle('adminDark',dark);const b=q('#themeToggle');if(b)b.textContent=dark?'☀':'◐'}
  window.toggleThemeV7=function(){localStorage.setItem(LS_THEME,localStorage.getItem(LS_THEME)==='dark'?'light':'dark');applyTheme()};

  function bindGlobalSearch(){const input=q('#globalSearch'),box=q('#globalSearchResults');if(!input||!box)return;input.oninput=()=>{const term=input.value.trim().toLowerCase();if(term.length<2){box.innerHTML='';box.classList.remove('show');return}const res=[];state.trips.filter(t=>`${t.name} ${t.destination}`.toLowerCase().includes(term)).slice(0,4).forEach(t=>res.push({type:'Passeio',title:t.name,sub:`${date(t.trip_date)} • ${t.destination||''}`,onclick:`openTripV7('${t.id}')`}));state.reservations.filter(r=>`${r.responsible_name} ${r.email} ${r.responsible_cpf} ${r.protocol||''} ${(r.participants||[]).map(p=>p.full_name+' '+p.cpf).join(' ')}`.toLowerCase().includes(term)).slice(0,8).forEach(r=>res.push({type:'Reserva',title:r.responsible_name,sub:`${state.trips.find(t=>t.id===r.trip_id)?.name||''} • ${r.protocol||''}`,onclick:`reservationModal('${r.trip_id}','${r.id}')`}));box.innerHTML=res.length?res.map(x=>`<button onclick="${x.onclick};document.getElementById('globalSearchResults').classList.remove('show')"><small>${x.type}</small><strong>${esc(x.title)}</strong><span>${esc(x.sub)}</span></button>`).join(''):'<div class="searchEmpty">Nenhum resultado.</div>';box.classList.add('show')};document.addEventListener('click',e=>{if(!e.target.closest('.globalSearchWrap'))box.classList.remove('show')},{once:true})}
  window.openTripV7=function(id){state.tab='trips';renderAdmin();setTimeout(()=>{const row=q(`[data-trip-row="${id}"]`);row?.scrollIntoView({behavior:'smooth',block:'center'});row?.classList.add('flashRow');setTimeout(()=>row?.classList.remove('flashRow'),1600)},100)};

  window.renderAdmin=function(){
    if(!q('.admin'))app.innerHTML=adminShell();
    qa('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.onclick=()=>{state.tab=b.dataset.tab;toggleAdminSide(false);renderAdmin()}});
    const nt=q('#newTrip');if(nt)nt.onclick=()=>roleCanManage()?tripModal():toast('Seu perfil não pode criar passeios.','error');
    const lo=q('#logout');if(lo)lo.onclick=async()=>{clearListeners();await auth.signOut();loginLayout()};
    q('#themeToggle')?.addEventListener('click',toggleThemeV7);
    applyTheme();setNetworkUI?.();updateNotificationBadge?.();bindGlobalSearch();
    const sync=q('#sync');if(sync&&navigator.onLine)sync.textContent=`☁ Sincronizado ${state.sync?state.sync.toLocaleTimeString('pt-BR'):''}`;
    const titles={dashboard:'Visão geral',trips:'Passeios',people:'Participantes',finance:'Financeiro',day:'Dia do passeio',reports:'Relatórios',pending:'Pendências',communications:'Comunicações',feedback:'Avaliações',notifications:'Notificações',settings:'Configurações',audit:'Histórico',trash:'Lixeira'};if(q('#pageTitle'))q('#pageTitle').textContent=titles[state.tab]||'Gestão';
    if(state.tab==='dashboard')renderDashboardV7();else if(state.tab==='trips')renderTripsV7();else if(state.tab==='people')renderPeopleV7();else if(state.tab==='finance')renderFinanceV7();else if(state.tab==='day')renderDayMode();else if(state.tab==='reports')renderReportsV7();else if(state.tab==='pending')renderPendingV7();else if(state.tab==='communications')renderCommunicationsV7();else if(state.tab==='feedback')renderFeedbackV7();else if(state.tab==='notifications')renderNotifications();else if(state.tab==='settings')renderSettingsV7();else if(state.tab==='audit')renderAuditV7();else if(state.tab==='trash')renderTrashV7();
  };
  try{renderAdmin=window.renderAdmin}catch(_){ }

  function peopleForTrip(id,includeCancelled=false){const out=[];state.reservations.filter(r=>r.trip_id===id&&(includeCancelled||r.status!=='cancelled')).forEach(r=>(r.participants||[]).forEach((p,i)=>out.push({key:digits(p.cpf)||`${r.id}-${i}`,name:p.full_name,cpf:p.cpf,reservation:r,index:i,responsible:r.responsible_name,email:r.email})));return out}
  function totals(){const gross=state.reservations.reduce((s,r)=>s+Number(r.paid_amount||0),0),refund=state.reservations.reduce((s,r)=>s+Number(r.refunded_amount||0),0),net=gross-refund,expenses=state.expenses.reduce((s,e)=>s+Number(e.amount||0),0),profit=net-expenses,receivable=state.trips.reduce((s,t)=>s+Number(t.receivable||0),0);return{gross,refund,net,expenses,profit,receivable,margin:net?profit/net*100:0}}
  function occupancy(t){const total=Number(t.total_spots||0),used=Number(t.used_spots||0);return total?Math.round(used/total*100):0}
  function countdown(t){const d=dayDiff(t.trip_date);if(d<0)return'Já realizado';if(d===0)return'É hoje!';if(d===1)return'Amanhã';return`Faltam ${d} dias`}

  function renderDashboardV7(){
    const T=totals(),open=state.trips.filter(t=>t.status==='open'),seats=state.reservations.filter(r=>r.status!=='cancelled').reduce((s,r)=>s+Number(r.seats||0),0),pending=state.reservations.filter(r=>['pending','partial'].includes(r.payment_status)).length,canc=state.reservations.filter(r=>r.status==='cancel_requested').length;
    const next=[...open].filter(t=>dayDiff(t.trip_date)>=0).sort((a,b)=>String(a.trip_date).localeCompare(String(b.trip_date)))[0];
    const ranking=[...state.trips].sort((a,b)=>Number(b.used_spots||0)-Number(a.used_spots||0)).slice(0,5),profitRank=[...state.trips].sort((a,b)=>Number(b.profit||0)-Number(a.profit||0)).slice(0,5);
    const alerts=[];open.filter(t=>Number(t.remaining_spots||0)<=5).forEach(t=>alerts.push(`Últimas ${t.remaining_spots} vaga(s) em ${t.name}`));if(pending)alerts.push(`${pending} pagamento(s) pendente(s) ou parcial(is)`);if(canc)alerts.push(`${canc} pedido(s) de cancelamento para analisar`);
    q('#content').innerHTML=`${next?`<section class="welcomeV7"><div><span class="eyebrow">PRÓXIMO PASSEIO</span><h2>${esc(next.name)}</h2><p>${esc(next.destination||'')} • ${date(next.trip_date)} • <b>${countdown(next)}</b></p></div><div class="welcomeStats"><div><small>VAGAS</small><strong>${next.used_spots||0}/${next.total_spots||0}</strong></div><div><small>LOTAÇÃO</small><strong>${occupancy(next)}%</strong></div><button class="btn primary" onclick="state.dayTrip='${next.id}';state.tab='day';renderAdmin()">Abrir operação</button></div></section>`:''}<div class="metrics premiumMetrics"><div class="metric"><span>PARTICIPAÇÕES</span><strong>${seats}</strong><small>vagas cadastradas</small></div><div class="metric"><span>RECEITA LÍQUIDA</span><strong>${brl(T.net)}</strong><small>bruto - reembolsos</small></div><div class="metric"><span>DESPESAS</span><strong>${brl(T.expenses)}</strong><small>custos realizados</small></div><div class="metric metricProfit"><span>RESULTADO</span><strong>${brl(T.profit)}</strong><small>margem ${T.margin.toFixed(1)}%</small></div><div class="metric"><span>A RECEBER</span><strong>${brl(T.receivable)}</strong><small>saldo estimado</small></div></div><div class="dashGridV7"><section class="panel"><div class="panelHead"><div><span class="eyebrow">AGENDA</span><h2>Próximos passeios</h2></div></div>${tripTableV7(open.slice(0,6),false)}</section><section class="panel alertPanel"><div class="panelHead"><div><span class="eyebrow">ATENÇÃO</span><h2>Central de alertas</h2></div><button class="btn ghost" onclick="state.tab='pending';renderAdmin()">Ver tudo</button></div><div class="alertList">${alerts.length?alerts.map((a,i)=>`<div><span>${i+1}</span><p>${esc(a)}</p></div>`).join(''):'<div class="allGood">✓ Tudo em ordem por aqui.</div>'}</div></section></div><div class="dashGridV7"><section class="panel"><div class="panelHead"><div><span class="eyebrow">POPULARIDADE</span><h2>Passeios mais vendidos</h2></div></div><div class="rankList">${ranking.map((t,i)=>`<div><span>${i+1}</span><strong>${esc(t.name)}</strong><div class="rankBar"><i style="width:${Math.min(100,occupancy(t))}%"></i></div><b>${t.used_spots||0}</b></div>`).join('')}</div></section><section class="panel"><div class="panelHead"><div><span class="eyebrow">RESULTADO</span><h2>Maior lucro</h2></div></div><div class="rankList">${profitRank.map((t,i)=>`<div><span>${i+1}</span><strong>${esc(t.name)}</strong><div class="rankBar"><i style="width:${Math.max(2,Math.min(100,profitRank[0]?.profit?Number(t.profit||0)/Number(profitRank[0].profit||1)*100:0))}%"></i></div><b>${brl(t.profit||0)}</b></div>`).join('')}</div></section></div>`;
  }

  function tripTableV7(list,actions=true){const F=favs();return `<div class="tableWrap"><table class="table v7Table"><thead><tr><th></th><th>Passeio</th><th>Data</th><th>Lotação</th><th>Receita</th><th>Despesas</th><th>Resultado</th><th>Status</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${list.map(t=>`<tr data-trip-row="${t.id}"><td><button class="starBtn ${F.has(t.id)?'on':''}" onclick="toggleFavorite('${t.id}')">★</button></td><td><strong>${esc(t.name)}</strong><small>${esc(t.destination||'')} • ${countdown(t)}</small></td><td>${date(t.trip_date)}</td><td><div class="occupancyCell"><b>${t.used_spots||0}/${t.total_spots||0}</b><div><i style="width:${occupancy(t)}%"></i></div><small>${occupancy(t)}%</small></div></td><td>${brl(t.net_revenue||0)}</td><td>${brl(t.expenses||0)}</td><td><strong>${brl(t.profit||0)}</strong></td><td><span class="pill ${t.status}">${status[t.status]||t.status}</span></td>${actions?`<td><div class="actions"><button title="Copiar link" onclick="copyLink('${t.id}')">🔗</button><button title="PDF Premium" onclick="pdfTrip('${t.id}')">PDF</button><button title="Operação" onclick="state.dayTrip='${t.id}';state.tab='day';renderAdmin()">☀</button>${roleCanManage()?`<button title="Editar" onclick="tripModal('${t.id}')">✎</button><button title="Duplicar" onclick="duplicateTripV7('${t.id}')">⧉</button><button title="Excluir para lixeira" class="dangerMini" onclick="deleteTrip('${t.id}')">⌫</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
  window.tripTable=tripTableV7;

  function renderTripsV7(){const F=favs(),list=[...state.trips].sort((a,b)=>(F.has(b.id)?1:0)-(F.has(a.id)?1:0)||String(a.trip_date).localeCompare(String(b.trip_date)));q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">AGENDA COMPLETA</span><h2>Passeios</h2><p>Favoritos aparecem primeiro. Duplique passeios recorrentes sem preencher tudo novamente.</p></div><div class="toolbar"><button class="btn ghost" onclick="backupV7()">Backup</button>${roleCanManage()?'<button class="btn primary" onclick="tripModal()">+ Cadastrar</button>':''}</div></div>${tripTableV7(list,true)}</section>`}

  window.duplicateTripV7=async function(id){if(!roleCanManage())return toast('Sem permissão.','error');const t=state.trips.find(x=>x.id===id);if(!t)return;const newDate=prompt(`Nova data para a cópia de ${t.name} (AAAA-MM-DD):`,todayISO());if(!newDate)return;const copy={...t};delete copy.id;delete copy.net_revenue;delete copy.expenses;delete copy.profit;delete copy.receivable;delete copy.gross_revenue;delete copy.refunds;copy.name=`${t.name} — nova data`;copy.trip_date=newDate;copy.status='draft';copy.used_spots=0;copy.remaining_spots=Number(copy.total_spots||0);copy.created_at=firebase.firestore.FieldValue.serverTimestamp();copy.updated_at=copy.created_at;const r=await db.collection('trips').add(copy);await audit('duplicate','trip',r.id,`Passeio duplicado a partir de ${t.name}`);toast('Passeio duplicado como rascunho.')};

  function clientTripsByCpf(){const map=new Map();state.reservations.filter(r=>r.status!=='cancelled').forEach(r=>(r.participants||[]).forEach(p=>{const k=digits(p.cpf);if(!k)return;if(!map.has(k))map.set(k,new Set());map.get(k).add(r.trip_id)}));return map}
  function renderPeopleV7(){const tripsByCpf=clientTripsByCpf(),rs=typeof filteredReservations==='function'?filteredReservations():state.reservations;q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">CLIENTES E RESERVAS</span><h2>Participantes</h2><p>CPF protegido por padrão. Abra a ficha para consultar dados completos e histórico.</p></div><div class="toolbar"><button class="btn ghost" onclick="insuranceCsvV7('${state.selectedTrip||''}')">Seguro CSV</button><button class="btn ghost" onclick="csv()">CSV completo</button></div></div><div class="filters"><input id="search" placeholder="Buscar nome, CPF, e-mail ou protocolo" value="${esc(state.search||'')}"><select id="filter"><option value="">Todos os passeios</option>${state.trips.map(t=>`<option value="${t.id}" ${t.id===state.selectedTrip?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="tableWrap"><table class="table"><thead><tr><th>Responsável</th><th>Passeio</th><th>Pessoas</th><th>Cliente</th><th>Financeiro</th><th>Status</th><th></th></tr></thead><tbody>${rs.map(r=>{const first=digits(r.responsible_cpf),count=tripsByCpf.get(first)?.size||1;return`<tr><td><strong>${esc(r.responsible_name)}</strong><small>${esc(r.email)}<br>${maskCpf(r.responsible_cpf)} • ${esc(r.protocol||'sem protocolo')}</small></td><td>${esc(state.trips.find(t=>t.id===r.trip_id)?.name||'')}</td><td><strong>${r.seats||0}</strong><small>${(r.participants||[]).map(p=>esc(p.full_name)).join(', ')}</small></td><td><span class="clientBadge ${count>1?'returning':''}">${count>1?`Recorrente • ${count} viagens`:'1ª viagem'}</span></td><td><strong>${brl(Number(r.paid_amount||0)-Number(r.refunded_amount||0))}</strong><small>${status[r.payment_status]||r.payment_status}</small></td><td><span class="pill ${r.status}">${status[r.status]||r.status}</span></td><td><div class="actions"><button onclick="participantDetailV7('${r.trip_id}','${r.id}')">Ficha</button><button onclick="reservationModal('${r.trip_id}','${r.id}')">Editar</button>${roleCanManage()?`<button class="dangerMini" onclick="deleteReservation('${r.trip_id}','${r.id}')">⌫</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div></section>`;q('#search').oninput=e=>{state.search=e.target.value;renderPeopleV7()};q('#filter').onchange=e=>{state.selectedTrip=e.target.value;renderPeopleV7()}}

  window.participantDetailV7=function(tripId,id){const r=state.reservations.find(x=>x.trip_id===tripId&&x.id===id),t=state.trips.find(x=>x.id===tripId);if(!r)return;const history=[];const cpfs=new Set((r.participants||[]).map(p=>digits(p.cpf)));state.reservations.forEach(x=>(x.participants||[]).forEach(p=>{if(cpfs.has(digits(p.cpf)))history.push({trip:state.trips.find(t=>t.id===x.trip_id),r:x})}));modal(`<div class="modalHead"><div><span class="eyebrow">FICHA DA RESERVA</span><h2>${esc(r.responsible_name)}</h2><small>${esc(t?.name||'')}</small></div><button class="iconClose" onclick="closeModalV7()">✕</button></div><div class="modalBody"><div class="detailGrid"><div><small>PROTOCOLO</small><strong>${esc(r.protocol||'—')}</strong></div><div><small>E-MAIL</small><strong>${esc(r.email||'—')}</strong></div><div><small>CPF RESPONSÁVEL</small><strong>${cpf(r.responsible_cpf)}</strong></div><div><small>VALOR LÍQUIDO</small><strong>${brl(Number(r.paid_amount||0)-Number(r.refunded_amount||0))}</strong></div></div><h3>Participantes</h3><div class="peopleDetail">${(r.participants||[]).map((p,i)=>`<div><span>${i+1}. ${esc(p.full_name)}</span><b>${cpf(p.cpf)}</b></div>`).join('')}</div>${r.registration_answers?`<h3>Opções da reserva</h3><div class="answerBox">${Object.values(r.registration_answers).map(x=>`<p><b>${esc(x.label||'')}</b>: ${esc(x.value||'')}</p>`).join('')}</div>`:''}<h3>Histórico de viagens</h3><div class="timelineList">${history.sort((a,b)=>String(b.trip?.trip_date).localeCompare(String(a.trip?.trip_date))).map(h=>`<div><span>${date(h.trip?.trip_date)}</span><strong>${esc(h.trip?.name||'Passeio')}</strong><small>${status[h.r.status]||h.r.status}</small></div>`).join('')}</div></div><div class="modalFoot"><button class="btn ghost" onclick="closeModalV7()">Fechar</button></div>`)};

  function renderFinanceV7(){if(!roleCanFinance()){q('#content').innerHTML='<div class="empty"><h3>Acesso restrito</h3><p>Seu perfil não possui acesso ao financeiro.</p></div>';return}const filter=state.financeTripFilter||'',trips=filter?state.trips.filter(t=>t.id===filter):state.trips,ids=new Set(trips.map(t=>t.id)),rs=state.reservations.filter(r=>ids.has(r.trip_id)),es=state.expenses.filter(e=>ids.has(e.trip_id)),gross=rs.reduce((s,r)=>s+Number(r.paid_amount||0),0),refund=rs.reduce((s,r)=>s+Number(r.refunded_amount||0),0),net=gross-refund,exp=es.reduce((s,e)=>s+Number(e.amount||0),0),profit=net-exp,receivable=trips.reduce((s,t)=>s+Number(t.receivable||0),0);q('#content').innerHTML=`<div class="financeTop"><select id="finTrip"><option value="">Todos os passeios</option>${state.trips.map(t=>`<option value="${t.id}" ${filter===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button class="btn primary" onclick="expenseModal('${filter}')">+ Despesa</button></div><div class="metrics premiumMetrics"><div class="metric"><span>RECEBIDO BRUTO</span><strong>${brl(gross)}</strong></div><div class="metric"><span>REEMBOLSOS</span><strong>${brl(refund)}</strong></div><div class="metric"><span>RECEITA LÍQUIDA</span><strong>${brl(net)}</strong></div><div class="metric"><span>DESPESAS</span><strong>${brl(exp)}</strong></div><div class="metric metricProfit"><span>LUCRO / RESULTADO</span><strong>${brl(profit)}</strong></div><div class="metric"><span>A RECEBER</span><strong>${brl(receivable)}</strong></div></div><section class="panel"><div class="panelHead"><div><span class="eyebrow">PREVISTO X REALIZADO</span><h2>Resultado por passeio</h2></div></div><div class="tableWrap"><table class="table"><thead><tr><th>Passeio</th><th>Custo previsto</th><th>Despesa real</th><th>Receita líquida</th><th>Resultado</th><th>Margem</th><th>Ponto de equilíbrio</th></tr></thead><tbody>${trips.map(t=>{const margin=Number(t.net_revenue||0)?Number(t.profit||0)/Number(t.net_revenue||1)*100:0,price=Number(t.default_price||0),breakeven=price?Math.ceil(Number(t.expenses||0)/price):0;return`<tr><td><strong>${esc(t.name)}</strong></td><td>${brl(t.estimated_cost||0)}</td><td>${brl(t.expenses||0)}</td><td>${brl(t.net_revenue||0)}</td><td><strong>${brl(t.profit||0)}</strong></td><td>${margin.toFixed(1)}%</td><td>${breakeven?`${breakeven} vaga(s)`:'—'}</td></tr>`}).join('')}</tbody></table></div></section><section class="panel"><div class="panelHead"><div><span class="eyebrow">CONTAS A RECEBER</span><h2>Pagamentos pendentes</h2></div></div><div class="tableWrap"><table class="table"><thead><tr><th>Cliente</th><th>Passeio</th><th>Status</th><th>Pago</th><th>Estimado</th><th>Saldo</th><th></th></tr></thead><tbody>${rs.filter(r=>!['paid','refunded','cancelled'].includes(r.payment_status)).map(r=>{const t=state.trips.find(x=>x.id===r.trip_id),expected=Number(t?.default_price||0)*Number(r.seats||0),paid=Number(r.paid_amount||0),balance=Math.max(0,expected-paid);return`<tr><td><strong>${esc(r.responsible_name)}</strong><small>${esc(r.email||'')}</small></td><td>${esc(t?.name||'')}</td><td>${status[r.payment_status]||r.payment_status}</td><td>${brl(paid)}</td><td>${brl(expected)}</td><td><strong>${brl(balance)}</strong></td><td><button class="btn ghost" onclick="reservationModal('${r.trip_id}','${r.id}')">Atualizar</button></td></tr>`}).join('')||'<tr><td colspan="7">Nenhuma pendência financeira.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panelHead"><div><span class="eyebrow">DESPESAS</span><h2>Lançamentos</h2></div></div><div class="tableWrap"><table class="table"><thead><tr><th>Data</th><th>Passeio</th><th>Categoria</th><th>Descrição</th><th>Valor</th><th></th></tr></thead><tbody>${es.map(e=>`<tr><td>${date(e.expense_date)}</td><td>${esc(state.trips.find(t=>t.id===e.trip_id)?.name||'')}</td><td>${esc(e.category||'')}</td><td>${esc(e.description||'')}</td><td><strong>${brl(e.amount)}</strong></td><td>${roleCanFinance()?`<button class="btn danger" onclick="deleteExpense('${e.id}')">Excluir</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;q('#finTrip').onchange=e=>{state.financeTripFilter=e.target.value;renderFinanceV7()}}

  async function loadOps(tripId){try{const s=await db.collection('trips').doc(tripId).collection('operations').get();const out={};s.docs.forEach(d=>out[d.id]={id:d.id,...d.data()});state.dayOps=out}catch(e){toast(friendly(e),'error')}}
  async function renderDayMode(){if(!roleCanOperate()){q('#content').innerHTML='<div class="empty"><h3>Acesso restrito</h3></div>';return}const selected=state.dayTrip||state.trips.find(t=>t.status==='open')?.id||state.trips[0]?.id||'';state.dayTrip=selected;if(!selected){q('#content').innerHTML='<div class="empty"><h3>Nenhum passeio cadastrado</h3></div>';return}await loadOps(selected);const t=state.trips.find(x=>x.id===selected),people=peopleForTrip(selected),present=people.filter(p=>state.dayOps[p.key]?.present).length,rooms=Array.isArray(t?.rooms)?t.rooms:[],vehicles=Array.isArray(t?.vehicles)?t.vehicles:[],check=t?.checklist||{};q('#content').innerHTML=`<div class="dayHeader"><div><span class="eyebrow">MODO DIA DO PASSEIO</span><h2>${esc(t?.name||'')}</h2><p>${date(t?.trip_date)} • ${people.length} participante(s)</p></div><select id="dayTripSelect">${state.trips.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)} — ${date(x.trip_date)}</option>`).join('')}</select></div><div class="dayStats"><div><span>Presentes</span><strong>${present}/${people.length}</strong></div><div><span>Ausentes / não marcados</span><strong>${people.length-present}</strong></div><div><span>Quartos</span><strong>${rooms.length}</strong></div><div><span>Veículos</span><strong>${vehicles.length}</strong></div></div><div class="dayGrid"><section class="panel"><div class="panelHead"><div><span class="eyebrow">PRESENÇA MANUAL</span><h2>Lista do dia</h2><p>Funciona com dados já carregados offline e sincroniza quando a internet voltar.</p></div><div class="toolbar"><button class="btn ghost" onclick="pdfTrip('${selected}')">PDF</button><button class="btn ghost" onclick="insuranceCsvV7('${selected}')">Seguro</button></div></div><div class="dayPeople">${people.map((p,i)=>{const o=state.dayOps[p.key]||{};return`<div class="dayPerson ${o.present?'present':''}"><button class="presenceBtn" onclick="togglePresenceV7('${selected}','${p.key}',${!o.present},'${encodeURIComponent(p.name)}','${digits(p.cpf)}')">${o.present?'✓':'○'}</button><div class="dayPersonMain"><strong>${i+1}. ${esc(p.name)}</strong><small>${maskCpf(p.cpf)} • ${esc(p.responsible||'')}</small></div><div class="dayAlloc"><select onchange="saveOpFieldV7('${selected}','${p.key}','room',this.value,'${encodeURIComponent(p.name)}','${digits(p.cpf)}')"><option value="">Sem quarto</option>${rooms.map(r=>`<option value="${esc(r.name)}" ${o.room===r.name?'selected':''}>${esc(r.name)}</option>`).join('')}</select><select onchange="saveOpFieldV7('${selected}','${p.key}','vehicle',this.value,'${encodeURIComponent(p.name)}','${digits(p.cpf)}')"><option value="">Sem veículo</option>${vehicles.map(v=>`<option value="${esc(v.name)}" ${o.vehicle===v.name?'selected':''}>${esc(v.name)}</option>`).join('')}</select><input placeholder="Assento" value="${esc(o.seat||'')}" onchange="saveOpFieldV7('${selected}','${p.key}','seat',this.value,'${encodeURIComponent(p.name)}','${digits(p.cpf)}')"></div></div>`}).join('')}</div></section><aside class="daySide"><section class="panel"><div class="panelHead"><div><span class="eyebrow">ESTRUTURA</span><h2>Quartos e veículos</h2></div><button class="btn ghost" onclick="structureModalV7('${selected}')">Configurar</button></div><div class="structureSummary"><h4>Quartos</h4>${rooms.length?rooms.map(r=>`<div><span>${esc(r.name)}</span><b>${esc(r.type||'')} • ${r.capacity||0} vagas</b></div>`).join(''):'<p>Nenhum quarto configurado.</p>'}<h4>Veículos</h4>${vehicles.length?vehicles.map(v=>`<div><span>${esc(v.name)}</span><b>${esc(v.driver||'')} ${v.plate?'• '+esc(v.plate):''} • ${v.capacity||0} lugares</b></div>`).join(''):'<p>Nenhum veículo configurado.</p>'}</div></section><section class="panel"><div class="panelHead"><div><span class="eyebrow">CHECKLIST</span><h2>Pré-passeio</h2></div></div><div class="checkListV7">${DEFAULT_CHECKLIST.map(([k,l])=>`<label><input type="checkbox" ${check[k]?'checked':''} onchange="saveChecklistV7('${selected}','${k}',this.checked)"><span>${esc(l)}</span></label>`).join('')}</div></section></aside></div>`;q('#dayTripSelect').onchange=e=>{state.dayTrip=e.target.value;renderDayMode()}}

  window.togglePresenceV7=async function(tripId,key,present,nameEnc,cpfNum){try{await db.collection('trips').doc(tripId).collection('operations').doc(key).set({participant_name:decodeURIComponent(nameEnc),cpf:cpfNum,present,updated_at:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});state.dayOps[key]={...(state.dayOps[key]||{}),present};renderDayMode()}catch(e){toast(friendly(e),'error')}};
  window.saveOpFieldV7=async function(tripId,key,field,value,nameEnc,cpfNum){try{await db.collection('trips').doc(tripId).collection('operations').doc(key).set({participant_name:decodeURIComponent(nameEnc),cpf:cpfNum,[field]:value,updated_at:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});state.dayOps[key]={...(state.dayOps[key]||{}),[field]:value};toast('Atualizado.')}catch(e){toast(friendly(e),'error')}};
  window.saveChecklistV7=async function(tripId,key,value){const t=state.trips.find(x=>x.id===tripId),next={...(t?.checklist||{}),[key]:value};try{await db.collection('trips').doc(tripId).update({checklist:next,updated_at:firebase.firestore.FieldValue.serverTimestamp()});if(t)t.checklist=next;await audit('checklist','trip',tripId,`${DEFAULT_CHECKLIST.find(x=>x[0]===key)?.[1]||key}: ${value?'concluído':'reaberto'}`);toast('Checklist atualizado.')}catch(e){toast(friendly(e),'error')}};

  window.structureModalV7=function(tripId){const t=state.trips.find(x=>x.id===tripId),rooms=Array.isArray(t?.rooms)?t.rooms:[],vehicles=Array.isArray(t?.vehicles)?t.vehicles:[];modal(`<form id="structureForm"><div class="modalHead"><div><span class="eyebrow">OPERAÇÃO</span><h2>Quartos e veículos</h2><small>${esc(t?.name||'')}</small></div><button type="button" class="iconClose" onclick="closeModalV7()">✕</button></div><div class="modalBody"><div class="formBlock"><h3>Quartos</h3><p class="hint">Uma linha por quarto: Nome | Tipo | Capacidade</p><textarea name="rooms" rows="7" placeholder="Quarto 01 | Casal | 2\nQuarto 02 | Compartilhado | 4">${rooms.map(r=>`${r.name} | ${r.type||''} | ${r.capacity||''}`).join('\n')}</textarea></div><div class="formBlock"><h3>Veículos / ônibus</h3><p class="hint">Uma linha: Nome | Motorista | Placa | Capacidade</p><textarea name="vehicles" rows="7" placeholder="Ônibus 01 | Romário | ABC1D23 | 46">${vehicles.map(v=>`${v.name} | ${v.driver||''} | ${v.plate||''} | ${v.capacity||''}`).join('\n')}</textarea></div><div id="fm"></div></div><div class="modalFoot"><button type="button" class="btn ghost" onclick="closeModalV7()">Cancelar</button><button class="btn primary">Salvar estrutura</button></div></form>`);q('#structureForm').onsubmit=async e=>{e.preventDefault();const parse=(txt,kind)=>txt.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const p=line.split('|').map(x=>x.trim());return kind==='room'?{name:p[0],type:p[1]||'',capacity:Number(p[2]||0)}:{name:p[0],driver:p[1]||'',plate:p[2]||'',capacity:Number(p[3]||0)}});try{const rooms2=parse(e.target.rooms.value,'room'),vehicles2=parse(e.target.vehicles.value,'vehicle');await db.collection('trips').doc(tripId).update({rooms:rooms2,vehicles:vehicles2,updated_at:firebase.firestore.FieldValue.serverTimestamp()});if(t){t.rooms=rooms2;t.vehicles=vehicles2}await audit('structure','trip',tripId,'Quartos e veículos atualizados');closeModalV7();toast('Estrutura salva.');renderDayMode()}catch(x){q('#fm').innerHTML=`<div class="msg error">${esc(friendly(x))}</div>`}}}

  function renderPendingV7(){const rows=[];state.reservations.filter(r=>r.status==='cancel_requested').forEach(r=>rows.push({level:'high',type:'Cancelamento',text:`${r.responsible_name} • ${state.trips.find(t=>t.id===r.trip_id)?.name||''}`,action:`reservationModal('${r.trip_id}','${r.id}')`}));state.reservations.filter(r=>['pending','partial'].includes(r.payment_status)&&r.status!=='cancelled').forEach(r=>rows.push({level:'medium',type:'Pagamento',text:`${r.responsible_name} • ${state.trips.find(t=>t.id===r.trip_id)?.name||''}`,action:`reservationModal('${r.trip_id}','${r.id}')`}));state.trips.filter(t=>t.status==='open'&&Number(t.remaining_spots||0)<=5).forEach(t=>rows.push({level:'low',type:'Últimas vagas',text:`${t.name} • ${t.remaining_spots} restante(s)`,action:`openTripV7('${t.id}')`}));state.trips.filter(t=>t.status==='open'&&dayDiff(t.trip_date)>=0&&dayDiff(t.trip_date)<=3).forEach(t=>{const ck=t.checklist||{},missing=DEFAULT_CHECKLIST.filter(([k])=>!ck[k]);if(missing.length)rows.push({level:'medium',type:'Checklist',text:`${t.name} • ${missing.length} item(ns) pendente(s)`,action:`state.dayTrip='${t.id}';state.tab='day';renderAdmin()`})});q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">CENTRAL DE PENDÊNCIAS</span><h2>O que precisa da sua atenção</h2></div></div><div class="pendingList">${rows.length?rows.map(x=>`<button class="pendingItem ${x.level}" onclick="${x.action}"><span>${esc(x.type)}</span><strong>${esc(x.text)}</strong><b>→</b></button>`).join(''):'<div class="allGood big">✓ Nenhuma pendência crítica.</div>'}</div></section>`}

  async function logoData(){try{const r=await fetch('https://i.postimg.cc/JnF2F9Hw/LOGO-TRILHEIROS-Photoroom.png');const b=await r.blob();return await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(b)})}catch{return null}}
  window.pdfTrip=async function(id){if(!id)return toast('Selecione um passeio.','error');const t=state.trips.find(x=>x.id===id);if(!t)return toast('Passeio não encontrado.','error');const btn=document.activeElement,old=btn?.textContent;if(btn?.tagName==='BUTTON'){btn.disabled=true;btn.textContent='Gerando PDF...'}try{await ensurePdfLibraries();const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'}),people=peopleForTrip(id),rs=state.reservations.filter(r=>r.trip_id===id&&r.status!=='cancelled'),logo=await logoData();doc.setFillColor(7,50,38);doc.rect(0,0,210,58,'F');doc.setFillColor(216,173,66);doc.rect(0,58,210,2,'F');if(logo)try{doc.addImage(logo,'PNG',14,9,30,30)}catch(_){}doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(10);doc.text('TRILHEIROS DE RONDONÓPOLIS',logo?51:14,17);doc.setFontSize(22);doc.text('LISTA OFICIAL DE PARTICIPANTES',logo?51:14,29);doc.setFontSize(10);doc.setFont('helvetica','normal');doc.text(`${t.name}`,logo?51:14,39);doc.text(`${date(t.trip_date)} • ${t.destination||''}`,logo?51:14,46);doc.setTextColor(20,45,35);doc.setFont('helvetica','bold');doc.setFontSize(15);doc.text('Resumo do passeio',14,73);const summary=[['Participantes',String(people.length)],['Reservas',String(rs.length)],['Vagas ocupadas',`${t.used_spots||0}/${t.total_spots||0}`],['Status',status[t.status]||t.status]];summary.forEach((x,i)=>{const x0=14+i*46;doc.setFillColor(244,248,246);doc.roundedRect(x0,80,42,20,3,3,'F');doc.setTextColor(95,115,107);doc.setFontSize(7);doc.text(x[0].toUpperCase(),x0+3,87);doc.setTextColor(10,55,42);doc.setFontSize(12);doc.text(x[1],x0+3,95)});doc.setFontSize(9);doc.setTextColor(60,80,72);doc.text('Documento gerado pelo Trilheiros Gestão • Dados organizados para operação do passeio.',14,110);const body=people.map((p,i)=>[String(i+1).padStart(2,'0'),p.name,cpf(p.cpf),p.responsible||'']);doc.autoTable({startY:118,head:[['Nº','NOME DO PARTICIPANTE','CPF','RESPONSÁVEL']],body,theme:'grid',styles:{font:'helvetica',fontSize:8.3,cellPadding:2.7,textColor:[25,48,40],lineColor:[220,231,226],lineWidth:.15},headStyles:{fillColor:[7,50,38],textColor:[255,255,255],fontStyle:'bold',fontSize:8.5},alternateRowStyles:{fillColor:[247,250,248]},columnStyles:{0:{cellWidth:12,halign:'center'},1:{cellWidth:76},2:{cellWidth:40},3:{cellWidth:54}},margin:{left:14,right:14,bottom:16},didDrawPage:data=>{doc.setFontSize(7.5);doc.setTextColor(100);doc.text(`Trilheiros de Rondonópolis • ${t.name}`,14,291);doc.text(`Página ${data.pageNumber}`,190,291,{align:'right'})}});const pages=doc.internal.getNumberOfPages();for(let i=1;i<=pages;i++){doc.setPage(i);doc.setFontSize(7);doc.setTextColor(120);doc.text(`Gerado em ${new Date().toLocaleString('pt-BR')} • Total de participantes: ${people.length}`,14,286)}doc.save(`lista-oficial-${slug(t.name)}-${String(t.trip_date||'').slice(0,10)}.pdf`);await audit('pdf','trip',id,`PDF de participantes gerado (${people.length} pessoas)`)}catch(e){console.error(e);toast('Não foi possível gerar o PDF agora. Verifique sua internet e tente novamente.','error')}finally{if(btn?.tagName==='BUTTON'){btn.disabled=false;btn.textContent=old||'PDF'}}};
  try{pdfTrip=window.pdfTrip}catch(_){ }

  window.insuranceCsvV7=function(id){if(!id)return toast('Selecione um passeio para gerar a lista do seguro.','error');const t=state.trips.find(x=>x.id===id),people=peopleForTrip(id);if(!t)return;const lines=[['Nº','Nome completo','CPF','Passeio','Data'],...people.map((p,i)=>[i+1,p.name,digits(p.cpf),t.name,date(t.trip_date)])].map(r=>r.map(csvEscape).join(';'));download(`seguro-${slug(t.name)}.csv`, '\ufeff'+lines.join('\n'),'text/csv;charset=utf-8');toast(`Lista do seguro gerada com ${people.length} participantes.`)};

  async function driverPdfV7(id){const t=state.trips.find(x=>x.id===id);if(!t)return;await loadOps(id);await ensurePdfLibraries();const {jsPDF}=window.jspdf,doc=new jsPDF(),people=peopleForTrip(id).map(p=>({...p,...(state.dayOps[p.key]||{})})).sort((a,b)=>String(a.vehicle||'ZZ').localeCompare(String(b.vehicle||'ZZ'))||String(a.seat||'').localeCompare(String(b.seat||'')));doc.setFillColor(7,50,38);doc.rect(0,0,210,35,'F');doc.setTextColor(255);doc.setFontSize(19);doc.text('LISTA DE TRANSPORTE',14,17);doc.setFontSize(9);doc.text(`${t.name} • ${date(t.trip_date)}`,14,26);doc.autoTable({startY:43,head:[['Nº','Participante','Veículo','Assento']],body:people.map((p,i)=>[i+1,p.name,p.vehicle||'—',p.seat||'—']),headStyles:{fillColor:[7,50,38]},styles:{fontSize:9,cellPadding:2.5},margin:{left:14,right:14}});doc.save(`transporte-${slug(t.name)}.pdf`)}
  window.driverPdfV7=driverPdfV7;

  async function roomsPdfV7(id){const t=state.trips.find(x=>x.id===id);if(!t)return;await loadOps(id);await ensurePdfLibraries();const {jsPDF}=window.jspdf,doc=new jsPDF(),people=peopleForTrip(id).map(p=>({...p,...(state.dayOps[p.key]||{})})).sort((a,b)=>String(a.room||'ZZ').localeCompare(String(b.room||'ZZ')));doc.setFillColor(7,50,38);doc.rect(0,0,210,35,'F');doc.setTextColor(255);doc.setFontSize(19);doc.text('MAPA DE HOSPEDAGEM',14,17);doc.setFontSize(9);doc.text(`${t.name} • ${date(t.trip_date)}`,14,26);doc.autoTable({startY:43,head:[['Nº','Participante','CPF','Quarto']],body:people.map((p,i)=>[i+1,p.name,cpf(p.cpf),p.room||'—']),headStyles:{fillColor:[7,50,38]},styles:{fontSize:8.7,cellPadding:2.4},margin:{left:14,right:14}});doc.save(`quartos-${slug(t.name)}.pdf`)}
  window.roomsPdfV7=roomsPdfV7;

  function renderReportsV7(){q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">CENTRAL DE RELATÓRIOS</span><h2>Documentos profissionais</h2><p>Selecione o passeio e gere o documento necessário.</p></div></div><div class="reportTripSelect"><select id="reportTrip"><option value="">Selecione um passeio</option>${state.trips.map(t=>`<option value="${t.id}">${esc(t.name)} — ${date(t.trip_date)}</option>`).join('')}</select></div><div class="reportCards"><button onclick="pdfTrip(document.getElementById('reportTrip').value)"><span>PDF</span><strong>Lista oficial de participantes</strong><small>Nome e CPF de cada participante, capa premium e paginação.</small></button><button onclick="insuranceCsvV7(document.getElementById('reportTrip').value)"><span>CSV</span><strong>Lista para seguro</strong><small>Nome completo e CPF em formato fácil de enviar.</small></button><button onclick="roomsPdfV7(document.getElementById('reportTrip').value)"><span>PDF</span><strong>Mapa de hospedagem</strong><small>Participantes separados por quarto.</small></button><button onclick="driverPdfV7(document.getElementById('reportTrip').value)"><span>PDF</span><strong>Lista de transporte</strong><small>Veículo e assento, sem pontos de embarque.</small></button><button onclick="copySurveyV7(document.getElementById('reportTrip').value)"><span>LINK</span><strong>Avaliação pós-passeio</strong><small>Copie o link para os participantes avaliarem a experiência.</small></button><button onclick="backupV7()"><span>JSON</span><strong>Backup completo</strong><small>Passeios, reservas, despesas e configurações.</small></button></div></section>`}
  window.copySurveyV7=function(id){if(!id)return toast('Selecione um passeio.','error');const url=`${location.origin}/avaliacao/${id}`;navigator.clipboard?.writeText(url).then(()=>toast('Link de avaliação copiado.')).catch(()=>prompt('Copie o link:',url))};

  window.backupV7=function(){const data={exported_at:new Date().toISOString(),version:'V7',trips:state.trips,reservations:state.reservations,expenses:state.expenses,communications:state.commSettings||{},general:state.generalSettings||{}};download(`backup-trilheiros-${todayISO()}.json`,JSON.stringify(data,null,2));audit('backup','system','',`Backup exportado`);toast('Backup gerado.')};

  async function loadFeedback(){try{const all=[];for(const t of state.trips){const s=await db.collection('trips').doc(t.id).collection('feedback').get();s.docs.forEach(d=>all.push({id:d.id,trip_id:t.id,trip_name:t.name,...d.data()}))}state.feedback=all}catch(e){console.warn(e)}}
  async function renderFeedbackV7(){q('#content').innerHTML='<div class="empty">Carregando avaliações...</div>';await loadFeedback();const avg=state.feedback.length?state.feedback.reduce((s,x)=>s+Number(x.rating||0),0)/state.feedback.length:0;q('#content').innerHTML=`<div class="metrics"><div class="metric"><span>AVALIAÇÕES</span><strong>${state.feedback.length}</strong></div><div class="metric"><span>NOTA MÉDIA</span><strong>${avg.toFixed(1)} ★</strong></div><div class="metric"><span>RECOMENDARIA</span><strong>${state.feedback.length?Math.round(state.feedback.filter(x=>x.recommend==='sim').length/state.feedback.length*100):0}%</strong></div></div><section class="panel"><div class="panelHead"><div><span class="eyebrow">PÓS-PASSEIO</span><h2>Opinião dos participantes</h2></div></div><div class="feedbackList">${state.feedback.length?state.feedback.sort((a,b)=>Number(b.rating)-Number(a.rating)).map(f=>`<article><div class="feedbackHead"><strong>${esc(f.trip_name)}</strong><span>${'★'.repeat(Number(f.rating||0))}${'☆'.repeat(5-Number(f.rating||0))}</span></div>${f.liked?`<p><b>Gostou:</b> ${esc(f.liked)}</p>`:''}${f.improve?`<p><b>Melhorar:</b> ${esc(f.improve)}</p>`:''}<small>Indicaria: ${f.recommend==='sim'?'Sim':f.recommend==='talvez'?'Talvez':'Não'}</small></article>`).join(''):'<div class="empty">Ainda não há avaliações.</div>'}</div></section>`}

  function templateHelp(){return '<div class="templateHelp"><b>Campos automáticos:</b> {{nome}} {{passeio}} {{data}} {{destino}} {{saida}} {{participantes}} {{levar}} {{lembrete_extra}} {{protocolo}} {{politica}} {{avaliacao_link}}</div>'}
  function renderCommunicationsV7(){if(!roleCanManage()){q('#content').innerHTML='<div class="empty"><h3>Acesso restrito</h3></div>';return}const s={...EMAIL_DEFAULTS,...(state.commSettings||{})};q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">AUTOMAÇÃO DE E-MAIL</span><h2>Lembretes personalizados</h2><p>O envio automático usa GitHub Actions + Resend, sem Cloud Functions.</p></div><label class="switchLabel"><input id="emailEnabled" type="checkbox" ${s.enabled!==false?'checked':''}><span>Ativado</span></label></div><form id="commV7"><div class="commCard"><div class="commTag">3 DIAS ANTES</div><h3>“O passeio é esta semana!”</h3><label><span>Assunto</span><input name="s3" value="${esc(s.reminder_3d_subject)}"></label><label><span>Mensagem</span><textarea name="b3" rows="11">${esc(s.reminder_3d_body)}</textarea></label></div><div class="commCard featured"><div class="commTag">1 DIA ANTES</div><h3>“É amanhã!”</h3><label><span>Assunto</span><input name="s1" value="${esc(s.reminder_1d_subject)}"></label><label><span>Mensagem</span><textarea name="b1" rows="11">${esc(s.reminder_1d_body)}</textarea></label></div><div class="commCard"><div class="commTag">PÓS-PASSEIO</div><h3>Agradecimento + avaliação</h3><label class="check"><input name="postEnabled" type="checkbox" ${s.post_trip_enabled?'checked':''}><span>Enviar no dia seguinte ao passeio</span></label><label><span>Assunto</span><input name="postSubject" value="${esc(s.post_trip_subject)}"></label><label><span>Mensagem</span><textarea name="postBody" rows="8">${esc(s.post_trip_body)}</textarea></label></div>${templateHelp()}<div class="commActions"><button type="button" class="btn ghost" onclick="restoreEmailDefaultsV7()">Restaurar textos divertidos</button><button class="btn primary">Salvar comunicações</button></div><div id="commMsg"></div></form></section>`;q('#commV7').onsubmit=async e=>{e.preventDefault();const f=e.target,data={enabled:q('#emailEnabled').checked,reminder_3d_subject:f.s3.value.trim(),reminder_3d_body:f.b3.value.trim(),reminder_1d_subject:f.s1.value.trim(),reminder_1d_body:f.b1.value.trim(),post_trip_enabled:f.postEnabled.checked,post_trip_subject:f.postSubject.value.trim(),post_trip_body:f.postBody.value.trim(),updated_at:firebase.firestore.FieldValue.serverTimestamp()};try{await db.collection('settings').doc('communications').set(data,{merge:true});state.commSettings={...state.commSettings,...data};await audit('settings','communications','communications','Textos de e-mail atualizados');q('#commMsg').innerHTML='<div class="msg ok">Comunicações salvas.</div>'}catch(x){q('#commMsg').innerHTML=`<div class="msg error">${esc(friendly(x))}</div>`}}}
  window.restoreEmailDefaultsV7=function(){state.commSettings={...EMAIL_DEFAULTS};renderCommunicationsV7();toast('Textos padrão restaurados na tela. Clique em Salvar para confirmar.')};

  async function renderSettingsV7(){if(!roleCanManage()){q('#content').innerHTML='<div class="empty"><h3>Acesso restrito</h3></div>';return}q('#content').innerHTML='<div class="empty">Carregando configurações...</div>';let settings={};try{const s=await db.collection('settings').doc('general').get();settings=s.exists?s.data():{};state.generalSettings=settings}catch(_){ }let users=[];if(state.role==='owner')try{const u=await db.collection('admin_users').get();users=u.docs.map(d=>({id:d.id,...d.data()}))}catch(_){ }q('#content').innerHTML=`<div class="settingsGrid"><section class="panel"><div class="panelHead"><div><span class="eyebrow">IDENTIDADE</span><h2>Configurações gerais</h2></div></div><form id="generalSettings"><label><span>Nome da operação</span><input name="business" value="${esc(settings.business_name||'Trilheiros de Rondonópolis')}"></label><label><span>WhatsApp principal</span><input name="whatsapp" value="${esc(settings.whatsapp||'66 99692-6174')}"></label><label><span>Tempo para bloquear painel por inatividade (minutos)</span><input name="session" type="number" min="5" max="240" value="${Number(localStorage.getItem(LS_SESSION)||30)}"></label><label><span>Categorias financeiras padrão</span><textarea name="cats" rows="4">${esc((settings.expense_categories||['Transporte','Alimentação','Hospedagem','Seguro','Guia local','Day Use','Equipamentos','Taxas','Outros']).join(' | '))}</textarea></label><button class="btn primary">Salvar configurações</button><div id="genMsg"></div></form></section>${state.role==='owner'?`<section class="panel"><div class="panelHead"><div><span class="eyebrow">ACESSOS</span><h2>Equipe administrativa</h2><p>Crie acesso com perfil específico. O usuário recebe uma conta do Firebase Authentication.</p></div></div><form id="staffForm"><div class="grid two"><label><span>Nome</span><input name="name" required></label><label><span>E-mail</span><input name="email" type="email" required></label><label><span>Senha inicial</span><input name="password" type="password" minlength="6" required></label><label><span>Perfil</span><select name="role"><option value="admin">Administrador</option><option value="finance">Financeiro</option><option value="support">Apoio / operação</option></select></label></div><button class="btn primary" style="margin-top:12px">Criar acesso</button><div id="staffMsg"></div></form><div class="staffList">${users.length?users.map(u=>`<div><div><strong>${esc(u.name||u.email)}</strong><small>${esc(u.email)} • ${esc(u.role||'support')}</small></div><button class="btn ${u.active===false?'primary':'danger'}" onclick="toggleStaffV7('${u.id}',${u.active===false})">${u.active===false?'Ativar':'Desativar'}</button></div>`).join(''):'<p>Nenhum usuário adicional.</p>'}</div></section>`:''}</div>`;q('#generalSettings').onsubmit=async e=>{e.preventDefault();const f=e.target,data={business_name:f.business.value.trim(),whatsapp:f.whatsapp.value.trim(),expense_categories:f.cats.value.split('|').map(x=>x.trim()).filter(Boolean),updated_at:firebase.firestore.FieldValue.serverTimestamp()};await db.collection('settings').doc('general').set(data,{merge:true});localStorage.setItem(LS_SESSION,String(Math.max(5,Number(f.session.value||30))));state.generalSettings=data;resetIdle();audit('settings','general','general','Configurações gerais atualizadas');q('#genMsg').innerHTML='<div class="msg ok">Configurações salvas.</div>'};if(q('#staffForm'))q('#staffForm').onsubmit=async e=>{e.preventDefault();const f=e.target;try{let secondary;try{secondary=firebase.app('trilheirosStaffCreator')}catch{secondary=firebase.initializeApp(firebase.app().options,'trilheirosStaffCreator')}const c=await secondary.auth().createUserWithEmailAndPassword(f.email.value.trim(),f.password.value);await db.collection('admin_users').doc(c.user.uid).set({name:f.name.value.trim(),email:f.email.value.trim().toLowerCase(),role:f.role.value,active:true,created_at:firebase.firestore.FieldValue.serverTimestamp()});await secondary.auth().signOut();await audit('access','admin_user',c.user.uid,`Acesso criado para ${f.email.value}`);toast('Acesso criado.');renderSettingsV7()}catch(x){q('#staffMsg').innerHTML=`<div class="msg error">${esc(friendly(x))}</div>`}}}
  window.toggleStaffV7=async function(uid,active){if(state.role!=='owner')return;await db.collection('admin_users').doc(uid).update({active,updated_at:firebase.firestore.FieldValue.serverTimestamp()});await audit('access','admin_user',uid,active?'Acesso ativado':'Acesso desativado');renderSettingsV7()};

  async function renderAuditV7(){if(!roleCanManage()){q('#content').innerHTML='<div class="empty"><h3>Acesso restrito</h3></div>';return}q('#content').innerHTML='<div class="empty">Carregando histórico...</div>';try{const s=await db.collection('audit_logs').orderBy('created_at','desc').limit(200).get(),logs=s.docs.map(d=>({id:d.id,...d.data()}));q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">AUDITORIA</span><h2>Histórico de alterações</h2></div></div><div class="auditList">${logs.length?logs.map(l=>`<div><span class="auditIcon">↺</span><div><strong>${esc(l.summary||l.action)}</strong><small>${esc(l.user_email||'')} • ${l.created_at?.toDate?l.created_at.toDate().toLocaleString('pt-BR'):'—'}</small></div><em>${esc(l.entity||'')}</em></div>`).join(''):'<div class="empty">Nenhum registro ainda.</div>'}</div></section>`}catch(e){q('#content').innerHTML=`<div class="empty"><h3>Não foi possível carregar o histórico.</h3><p>${esc(friendly(e))}</p></div>`}}

  async function trashItem(type,id,data){await db.collection('trash').add({type,original_id:id,data,deleted_by:auth.currentUser?.email||'',deleted_at:firebase.firestore.FieldValue.serverTimestamp()})}
  window.deleteExpense=async function(id){if(!roleCanFinance())return toast('Sem permissão.','error');if(!requireOnline())return;const e=state.expenses.find(x=>x.id===id);if(!e||!confirm('Mover esta despesa para a lixeira?'))return;try{await trashItem('expense',id,e);await db.collection('expenses').doc(id).delete();await audit('delete','expense',id,`Despesa movida para lixeira: ${e.description||e.category}`);toast('Despesa movida para a lixeira.')}catch(x){toast(friendly(x),'error')}};
  try{deleteExpense=window.deleteExpense}catch(_){ }

  window.deleteReservation=async function(tripId,id){if(!roleCanManage())return toast('Sem permissão.','error');if(!requireOnline())return;const r=state.reservations.find(x=>x.trip_id===tripId&&x.id===id);if(!r)return;if(!confirm(`Mover a reserva de ${r.responsible_name} para a lixeira e devolver ${r.seats} vaga(s)?`))return;try{await trashItem('reservation',`${tripId}/${id}`,{trip_id:tripId,reservation:r});await db.runTransaction(async tx=>{const rr=db.collection('trips').doc(tripId).collection('reservations').doc(id),tr=db.collection('trips').doc(tripId),ts=await tx.get(tr);if(!ts.exists)throw Error('Passeio não encontrado.');const td=ts.data(),restore=r.status==='cancelled'?0:Number(r.seats||0);tx.delete(rr);if(restore)tx.update(tr,{remaining_spots:Number(td.remaining_spots||0)+restore,used_spots:Math.max(0,Number(td.used_spots||0)-restore),updated_at:firebase.firestore.FieldValue.serverTimestamp()})});await audit('delete','reservation',id,`Reserva movida para lixeira: ${r.responsible_name}`);toast('Reserva movida para a lixeira.')}catch(x){toast(friendly(x),'error')}};
  try{deleteReservation=window.deleteReservation}catch(_){ }

  window.deleteTrip=async function(id){if(!roleCanManage())return toast('Sem permissão.','error');if(!requireOnline())return;const t=state.trips.find(x=>x.id===id);if(!t)return;const typed=prompt(`Mover o passeio “${t.name}” para a lixeira?\n\nDigite EXCLUIR para confirmar:`);if(typed!=='EXCLUIR')return;try{const rs=state.reservations.filter(r=>r.trip_id===id),es=state.expenses.filter(e=>e.trip_id===id);await trashItem('trip',id,{trip:t,reservations:rs,expenses:es});for(const r of rs)await db.collection('trips').doc(id).collection('reservations').doc(r.id).delete();const ops=await db.collection('trips').doc(id).collection('operations').get();for(const d of ops.docs)await d.ref.delete();for(const e of es)await db.collection('expenses').doc(e.id).delete();await db.collection('trips').doc(id).delete();await audit('delete','trip',id,`Passeio movido para lixeira: ${t.name}`);closeModalV7();toast('Passeio movido para a lixeira.')}catch(x){toast(friendly(x),'error')}};
  try{deleteTrip=window.deleteTrip}catch(_){ }

  async function renderTrashV7(){if(!roleCanManage()){q('#content').innerHTML='<div class="empty"><h3>Acesso restrito</h3></div>';return}q('#content').innerHTML='<div class="empty">Carregando lixeira...</div>';try{const s=await db.collection('trash').orderBy('deleted_at','desc').limit(100).get(),items=s.docs.map(d=>({id:d.id,...d.data()}));q('#content').innerHTML=`<section class="panel"><div class="panelHead"><div><span class="eyebrow">LIXEIRA DE SEGURANÇA</span><h2>Itens excluídos</h2><p>Restaure quando necessário. A exclusão definitiva deve ser usada com cuidado.</p></div></div><div class="trashList">${items.length?items.map(x=>`<div><div><strong>${x.type==='trip'?esc(x.data?.trip?.name||'Passeio'):x.type==='reservation'?esc(x.data?.reservation?.responsible_name||'Reserva'):esc(x.data?.description||x.data?.category||'Despesa')}</strong><small>${esc(x.type)} • ${x.deleted_at?.toDate?x.deleted_at.toDate().toLocaleString('pt-BR'):'—'}</small></div><div class="toolbar"><button class="btn ghost" onclick="restoreTrashV7('${x.id}')">Restaurar</button><button class="btn danger" onclick="purgeTrashV7('${x.id}')">Excluir definitivo</button></div></div>`).join(''):'<div class="empty">Lixeira vazia.</div>'}</div></section>`}catch(e){q('#content').innerHTML=`<div class="empty"><p>${esc(friendly(e))}</p></div>`}}
  window.restoreTrashV7=async function(id){if(!requireOnline())return;const ref=db.collection('trash').doc(id),s=await ref.get();if(!s.exists)return;const x=s.data();try{if(x.type==='expense'){const d={...x.data};delete d.id;await db.collection('expenses').doc(x.original_id).set(d)}else if(x.type==='reservation'){const d=x.data.reservation,tripId=x.data.trip_id,copy={...d};delete copy.id;delete copy.trip_id;const tr=db.collection('trips').doc(tripId),rr=tr.collection('reservations').doc(x.original_id.split('/').pop());await db.runTransaction(async tx=>{const ts=await tx.get(tr);if(!ts.exists)throw Error('O passeio original não existe.');const td=ts.data(),seats=Number(copy.seats||0);if(Number(td.remaining_spots||0)<seats)throw Error('Não há vagas suficientes para restaurar.');tx.set(rr,copy);tx.update(tr,{remaining_spots:Number(td.remaining_spots)-seats,used_spots:Number(td.used_spots||0)+seats,updated_at:firebase.firestore.FieldValue.serverTimestamp()})})}else if(x.type==='trip'){const pack=x.data,trip={...pack.trip};delete trip.id;await db.collection('trips').doc(x.original_id).set(trip);for(const r of pack.reservations||[]){const c={...r};delete c.id;delete c.trip_id;await db.collection('trips').doc(x.original_id).collection('reservations').doc(r.id).set(c)}for(const e of pack.expenses||[]){const c={...e};delete c.id;await db.collection('expenses').doc(e.id).set(c)}}await ref.delete();await audit('restore','trash',id,`Item restaurado da lixeira (${x.type})`);toast('Item restaurado.');renderTrashV7()}catch(e){toast(friendly(e),'error')}};
  window.purgeTrashV7=async function(id){if(!confirm('Excluir definitivamente este item da lixeira? Esta ação não pode ser desfeita.'))return;await db.collection('trash').doc(id).delete();await audit('purge','trash',id,'Item excluído definitivamente');renderTrashV7()};

  document.addEventListener('DOMContentLoaded',applyTheme);
  setTimeout(applyTheme,200);
})();
